(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.015+t*0.2)*20 + Math.cos(y*0.012-t*0.15)*15;
  const w1y = Math.cos(y*0.015-t*0.18)*20 + Math.sin(x*0.013+t*0.22)*15;
  const wx = Math.sin((x+w1x)*0.02+t*0.3)*12 + Math.cos((y+w1y)*0.018-t*0.25)*8;
  const wy = Math.cos((y+w1y)*0.02-t*0.28)*12 + Math.sin((x+w1x)*0.019+t*0.32)*8;
  const sx = x+wx, sy = y+wy;
  const src = [
    [160+Math.sin(t*0.6)*100,80+Math.cos(t*0.4)*50,0.08,2.0,0.7],
    [320+Math.cos(t*0.5)*100,160+Math.sin(t*0.7)*50,0.1,1.7,0.8],
    [240+Math.sin(t*0.3+2)*140,120+Math.cos(t*0.5+1)*90,0.06,2.3,0.6],
    [120+Math.cos(t*0.8+1)*80,180+Math.sin(t*0.6+3)*60,0.12,1.5,0.9],
    [360+Math.sin(t*0.4+4)*90,60+Math.cos(t*0.9+2)*70,0.07,2.6,0.5],
    [240+Math.cos(t*0.35+5)*120,200+Math.sin(t*0.55)*80,0.09,1.9,0.75],
    [80+Math.sin(t*0.7+3)*60,40+Math.cos(t*0.5+2)*40,0.15,3.0,0.4],
    [400+Math.cos(t*0.45+1)*70,200+Math.sin(t*0.65+4)*50,0.13,2.8,0.45],
    [200+Math.sin(t*0.55+6)*50,220+Math.cos(t*0.75)*30,0.18,3.2,0.35]
  ];
  let aS=0,iS=0,wS=0;
  for(const[sX,sY,f,sp,w]of src){
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    aS+=Math.sin(d*f-t*sp)*w; iS+=Math.sin(d*f*0.7+t*sp*0.6+1.5)*w; wS+=w;
  }
  const act=aS/wS, inh=iS/wS;
  const bg1=(Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2;
  const bg2=Math.sin((sx+sy)*0.12+t*2.5)*0.2+Math.sin((sx-sy)*0.1-t*2)*0.2;
  const bg3=Math.sin(sx*0.08+sy*0.06-t*1.8)*0.15+Math.cos(sx*0.05-sy*0.09+t*1.4)*0.15;
  const bg=bg1+bg2+bg3;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2), ang=Math.atan2(sy-cy,sx-cx);
  const spiral=(Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2)+Math.sin(dist*0.07-ang*5+t*0.8))*0.3;
  const cell=Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.13)*Math.cos(sx*0.087-sy*0.05)+Math.sin((sx+sy)*0.1+t)*0.5)*1.5)*0.3;
  const cross=Math.sin(act*inh*2.5+t*0.3)*0.2;
  const reaction=Math.tanh((act-inh*0.7+bg*0.3+spiral+cross)*2.2);
  const micro=Math.tanh((Math.sin(sx*0.25+t*1.5)*Math.sin(sy*0.25-t*1.2)+Math.cos(dist*0.08-t)*0.5)*1.2)*0.15;
  const blend=reaction*0.65+cell*0.15+micro*0.1+spiral*0.1;
  const v=blend*0.5+0.5;
  const pal=[[5,12,52],[10,45,95],[15,90,120],[20,140,130],[80,175,110],[190,195,70],[220,160,55],[215,105,60],[185,60,65],[130,35,70],[70,20,65],[30,12,55],[5,12,52]];
  const idx=v*(pal.length-1), i=Math.min(idx|0,pal.length-2);
  const hShift=Math.sin(ang*2+t*0.5)*0.08;
  const f=Math.min(1,Math.max(0,idx-i+hShift));
  const lum=0.85+Math.sin(reaction*Math.PI)*0.15+Math.abs(spiral)*0.1;
  const edge=Math.abs(reaction)>0.65?1.0+(Math.abs(reaction)-0.65)*1.2:1.0;
  const vig=1.0-Math.sqrt((x-240)**2+(y-120)**2)/380*0.3;
  const sparkle=Math.max(0,Math.sin(act*12+t*5)*Math.sin(inh*10-t*4))*0.15;
  const el=lum*edge*vig+sparkle;
  return[
    Math.min(255,(pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*el)|0,
    Math.min(255,(pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*el)|0,
    Math.min(255,(pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*el)|0
  ];
}
